[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "{% set company_name = doc.company or (frappe.db.get_value("Project", doc.project, "company") if doc.project else "") %}
{% set company = frappe.get_doc("Company", company_name) if company_name else None %}
{% set company_logo = company.company_logo if company and company.get("company_logo") else "" %}
{% set project_name = frappe.db.get_value("Project", doc.project, "project_name") if doc.project else "" %}
{% set customer_name = frappe.db.get_value("Customer", doc.client, "customer_name") if doc.client else "" %}
{% set currency = doc.currency or "AED" %}
{% set print_date = frappe.utils.nowdate() %}

{% set ns = namespace(
  total_qty=0,
  total_cost=0,
  total_amount=0,
  total_margin=0,
  category_total=0,
  category_count=0,
  last_category="",
  row_no=0
) %}

<div class="qboq">
  <table class="qboq-head">
    <tr>
      <td class="qboq-brand">
        {% if company_logo %}
          <img src="{{ company_logo }}" class="qboq-logo">
        {% else %}
          <div class="qboq-company">{{ company.company_name if company else company_name or "" }}</div>
        {% endif %}
      </td>
      <td class="qboq-title-cell">
        <div class="qboq-title">BILL OF QUANTITIES</div>
        <div class="qboq-subtitle">{{ doc.name }}</div>
        <div class="qboq-meta-line">
          Rev {{ doc.revision_no or 0 }} | {{ doc.revision_status or doc.status or "Draft" }} | {{ frappe.utils.formatdate(print_date, "dd/MM/yyyy") }}
        </div>
      </td>
    </tr>
  </table>

  <table class="qboq-info">
    <tr>
      <td><div class="qboq-label">Project</div><div class="qboq-value">{{ project_name or doc.project or "" }}</div></td>
      <td><div class="qboq-label">Client</div><div class="qboq-value">{{ customer_name or doc.client or "" }}</div></td>
      <td><div class="qboq-label">Consultant</div><div class="qboq-value">{{ doc.consultant or "" }}</div></td>
      <td><div class="qboq-label">Contractor</div><div class="qboq-value">{{ company.company_name if company else company_name or "" }}</div></td>
    </tr>
    <tr>
      <td><div class="qboq-label">BOQ No.</div><div class="qboq-value">{{ doc.name }}</div></td>
      <td><div class="qboq-label">Currency</div><div class="qboq-value">{{ currency }}</div></td>
      <td>
        <div class="qboq-label">Built-Up Area</div>
        <div class="qboq-value">
          {% if doc.built_up_area %}
            {{ "{:,.2f}".format(doc.built_up_area or 0) }} {{ doc.bua_uom or "" }}
          {% else %}
            -
          {% endif %}
        </div>
      </td>
      <td><div class="qboq-label">Status</div><div class="qboq-value">{{ doc.status or "Draft" }}</div></td>
    </tr>
  </table>

  {% if doc.is_revision or doc.parent_boq or doc.revision_reason %}
    <table class="qboq-revision">
      <tr>
        <td><div class="qboq-label">Original BOQ</div><div class="qboq-value">{{ doc.original_boq or doc.name }}</div></td>
        <td><div class="qboq-label">Previous Revision</div><div class="qboq-value">{{ doc.parent_boq or "-" }}</div></td>
        <td><div class="qboq-label">Revision Date</div><div class="qboq-value">{{ frappe.utils.formatdate(doc.revision_date, "dd/MM/yyyy") if doc.revision_date else "-" }}</div></td>
        <td><div class="qboq-label">Active Revision</div><div class="qboq-value">{{ "Yes" if doc.is_active_revision else "No" }}</div></td>
      </tr>
      {% if doc.revision_reason %}
        <tr>
          <td colspan="4">
            <div class="qboq-label">Revision Reason</div>
            <div class="qboq-value">{{ doc.revision_reason }}</div>
          </td>
        </tr>
      {% endif %}
    </table>
  {% endif %}

  {% if doc.items %}
    <table class="qboq-items">
      <colgroup>
        <col style="width:4%;">
        <col style="width:44%;">
        <col style="width:8%;">
        <col style="width:8%;">
        <col style="width:13%;">
        <col style="width:18%;">
        <col style="width:5%;">
      </colgroup>

      <thead>
        <tr>
          <th class="c">#</th>
          <th>Category / Description</th>
          <th class="r">Qty</th>
          <th class="c">UOM</th>
          <th class="r">Unit Rate</th>
          <th class="r">Amount</th>
          <th>Notes</th>
        </tr>
      </thead>

      <tbody>
        {% for item in doc.items %}
          {% set category_name = frappe.db.get_value("BOQ Category", item.boq_category, "category_name") or item.boq_category or "Uncategorized" %}
          {% set item_amount = item.amount_after_margin or ((item.qty or 0) * (item.unit_rate or 0)) %}
          {% set cost_amount = item.amount or ((item.qty or 0) * (item.unit_cost or 0)) %}

          {% if item.boq_category != ns.last_category %}
            {% if not loop.first %}
              <tr class="qboq-cat-total">
                <td colspan="5">Subtotal - {{ frappe.db.get_value("BOQ Category", ns.last_category, "category_name") or ns.last_category or "Uncategorized" }}</td>
                <td colspan="2" class="r qboq-subtotal-amount">{{ frappe.utils.fmt_money(ns.category_total, currency=currency) }}</td>
              </tr>
            {% endif %}

            {% set ns.last_category = item.boq_category %}
            {% set ns.category_total = 0 %}
            {% set ns.category_count = 0 %}

            <tr class="qboq-cat-row">
              <td colspan="7">
                {{ category_name }}
                {% if item.boq_parent_category and item.boq_parent_category != category_name %}
                  <span>{{ item.boq_parent_category }}</span>
                {% endif %}
              </td>
            </tr>
          {% endif %}

          {% set ns.row_no = ns.row_no + 1 %}
          {% set ns.total_qty = ns.total_qty + (item.qty or 0) %}
          {% set ns.total_cost = ns.total_cost + cost_amount %}
          {% set ns.total_amount = ns.total_amount + item_amount %}
          {% set ns.total_margin = ns.total_margin + (item_amount - cost_amount) %}
          {% set ns.category_total = ns.category_total + item_amount %}
          {% set ns.category_count = ns.category_count + 1 %}

          <tr class="{{ 'deleted-row' if item.is_deleted_in_revision else '' }}">
            <td class="c">{{ ns.row_no }}</td>
            <td>
              <div class="item-name">{{ item.item_name or item.item or "" }}</div>
              {% if item.revision_item_status and item.revision_item_status != "Unchanged" %}
                <div class="revision-chip">{{ item.revision_item_status }}</div>
              {% endif %}
            </td>
            <td class="r">{{ "{:,.2f}".format(item.qty or 0).rstrip("0").rstrip(".") }}</td>
            <td class="c">{{ item.uom or "" }}</td>
            <td class="r">{{ frappe.utils.fmt_money(item.unit_rate or 0, currency=currency) }}</td>
            <td class="r bold">{{ frappe.utils.fmt_money(item_amount, currency=currency) }}</td>
            <td>{{ item.notes or "" }}</td>
          </tr>

          {% if loop.last %}
            <tr class="qboq-cat-total">
              <td colspan="5">Subtotal - {{ category_name }}</td>
              <td colspan="2" class="r qboq-subtotal-amount">{{ frappe.utils.fmt_money(ns.category_total, currency=currency) }}</td>
            </tr>
          {% endif %}
        {% endfor %}
      </tbody>
    </table>
  {% else %}
    <table class="qboq-empty">
      <tr><td>No BOQ items have been added.</td></tr>
    </table>
  {% endif %}

  <table class="qboq-bottom">
    <tr>
      <td class="qboq-notes">
        <div class="qboq-section-title">Summary</div>
        <table class="qboq-mini">
          <tr><td>Total Items</td><td>{{ ns.row_no }}</td></tr>
          <tr><td>Total Quantity</td><td>{{ "{:,.2f}".format(ns.total_qty).rstrip("0").rstrip(".") }}</td></tr>
          {% if doc.built_up_area %}
            <tr>
              <td>Rate per {{ doc.bua_uom or "BUA" }}</td>
              <td>{{ frappe.utils.fmt_money(doc.rate_per_bua or ((doc.grand_total or ns.total_amount) / doc.built_up_area), currency=currency) }}</td>
            </tr>
          {% endif %}
        </table>
      </td>

      <td class="qboq-total-cell">
        <table class="qboq-totals">
          <tr><td>Total Cost</td><td>{{ frappe.utils.fmt_money(doc.total_cost or ns.total_cost, currency=currency) }}</td></tr>
          <tr><td>Total Margin</td><td>{{ frappe.utils.fmt_money(doc.total_margin or ns.total_margin, currency=currency) }}</td></tr>
          <tr><td>Margin %</td><td>{{ "{:,.2f}".format(doc.margin_percent or 0) }}%</td></tr>
          <tr class="grand"><td>Grand Total</td><td>{{ frappe.utils.fmt_money(doc.grand_total or ns.total_amount, currency=currency) }}</td></tr>
        </table>
      </td>
    </tr>
  </table>

  <table class="qboq-sign">
    <tr>
      <td><div class="sign-line"></div><div class="sign-label">Prepared By</div></td>
      <td><div class="sign-line"></div><div class="sign-label">Approved By</div></td>
      <td><div class="sign-line"></div><div class="sign-label">Client Signature</div></td>
    </tr>
  </table>
</div>

<style>
html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  margin: 0 !important;
  padding: 0 !important;
}

.qboq {
  font-family: Arial, sans-serif;
  font-size: 10.5px;
  color: #0f1e38;
  background: #ffffff;
  padding: 22px 26px;
  box-sizing: border-box;
}

.qboq-head {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin-bottom: 14px;
}

.qboq-brand {
  width: 42%;
  background: #071a33;
  padding: 18px 22px;
  vertical-align: middle;
}

.qboq-title-cell {
  width: 58%;
  background: #071a33;
  padding: 18px 22px;
  text-align: right;
  vertical-align: middle;
}

.qboq-logo {
  height: 52px;
  max-width: 220px;
  display: block;
}

.qboq-company {
  color: #ffffff;
  font-size: 17px;
  font-weight: 800;
}

.qboq-title {
  color: #ffffff;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: 2px;
}

.qboq-subtitle {
  color: #f0ca4a;
  font-size: 13px;
  margin-top: 4px;
  font-weight: 800;
}

.qboq-meta-line {
  color: #ffffff;
  font-size: 10px;
  margin-top: 4px;
}

.qboq-info,
.qboq-revision {
  width: 100%;
  border-collapse: collapse;
  border: 1px solid #dfe4ec;
  margin-bottom: 14px;
  table-layout: fixed;
}

.qboq-info td,
.qboq-revision td {
  width: 25%;
  padding: 9px 11px;
  background: #f8fafc;
  border-right: 1px solid #dfe4ec;
  border-bottom: 1px solid #dfe4ec;
  vertical-align: top;
}

.qboq-label {
  color: #071a33;
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.qboq-value {
  color: #0f1e38;
  font-size: 11px;
  font-weight: 800;
  margin-top: 3px;
  line-height: 1.35;
}

.qboq-items {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin-top: 14px;
}

.qboq-items thead th {
  background: #071a33 !important;
  color: #ffffff !important;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  padding: 11px 7px;
  border: 1px solid #071a33;
  vertical-align: middle;
  line-height: 1.2;
}

.qboq-items td {
  padding: 6px 7px;
  border: 1px solid #e3e7ef;
  vertical-align: top;
  line-height: 1.35;
  word-wrap: break-word;
}

.qboq-items tbody tr:nth-child(even) {
  background: #fbfcfe;
}

.qboq-cat-row td {
  background: #0f1e38 !important;
  color: #ffffff !important;
  font-weight: 800;
  text-transform: uppercase;
  font-size: 10px;
  letter-spacing: 0.5px;
  padding: 9px 8px;
  border-color: #0f1e38;
}

.qboq-cat-row span {
  color: #f0ca4a;
  font-size: 9px;
  font-weight: 700;
  margin-left: 8px;
}

.qboq-cat-total td {
  background: #dfe6f1 !important;
  color: #071a33;
  font-weight: 800;
  border-top: 2px solid #071a33;
}

.qboq-subtotal-amount {
  min-width: 150px;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 900;
  text-align: right;
}

.deleted-row td {
  color: #9b1c1c;
  text-decoration: line-through;
}

.item-name {
  font-weight: 800;
  color: #071a33;
}

.revision-chip {
  display: inline-block;
  margin-top: 3px;
  padding: 2px 5px;
  background: #071a33;
  color: #ffffff;
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
}

.c {
  text-align: center;
}

.r {
  text-align: right;
}

.bold {
  font-weight: 800;
}

.qboq-bottom {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin-top: 16px;
}

.qboq-notes {
  width: 50%;
  vertical-align: top;
  padding-right: 18px;
}

.qboq-total-cell {
  width: 50%;
  vertical-align: top;
}

.qboq-section-title {
  font-size: 8px;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #ffffff;
  background: #071a33;
  font-weight: 800;
  padding: 8px 10px;
  margin-bottom: 0;
}

.qboq-mini,
.qboq-totals {
  width: 100%;
  border-collapse: collapse;
  border: 1px solid #dfe4ec;
}

.qboq-mini td,
.qboq-totals td {
  padding: 8px 10px;
  border-bottom: 1px solid #e3e7ef;
}

.qboq-mini td:first-child,
.qboq-totals td:first-child {
  color: #071a33;
  font-weight: 800;
}

.qboq-mini td:last-child,
.qboq-totals td:last-child {
  text-align: right;
  font-weight: 800;
}

.qboq-totals .grand td {
  background: #071a33;
  color: #ffffff;
  font-size: 13px;
  font-weight: 800;
}

.qboq-empty {
  width: 100%;
  border-collapse: collapse;
  margin-top: 16px;
}

.qboq-empty td {
  padding: 24px;
  text-align: center;
  border: 1px solid #dfe4ec;
  color: #6b7a99;
}

.qboq-sign {
  width: 100%;
  border-collapse: collapse;
  margin-top: 58px;
}

.qboq-sign td {
  width: 33.33%;
  padding: 0 24px;
  text-align: center;
}

.sign-line {
  height: 42px;
  border-bottom: 1px solid #071a33;
}

.sign-label {
  margin-top: 7px;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  color: #071a33;
}

@media print {
  .qboq-items thead th {
    background: #071a33 !important;
    color: #ffffff !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .qboq-cat-row td,
  .qboq-totals .grand td,
  .qboq-section-title {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
}
</style>"}]
